  'update',
  $payload${"moduleId":"safety-qc","revisionType":"quiz","title":"Evaluación: Configuración Sensitiva vs Motora","quizTopicId":"sweep-gain","passScore":70,"maxAttempts":null,"shuffleQuestions":true,"shuffleOptions":true,"questions":[{"id":"gain-q1","sortOrder":0,"type":"single","difficulty":"basic","stem":"¿Qué ganancia, barrido y filtros asigna la lección al estudio motor?","options":[{"id":"gain-q1-a","text":"Ganancia 2–5 mV/div, barrido 2–5 ms/div y filtros de 2 Hz a 10 kHz.","isCorrect":true},{"id":"gain-q1-b","text":"Ganancia 10–20 µV/div, barrido 1–2 ms/div y filtros de 20 Hz a 2 kHz.","isCorrect":false},{"id":"gain-q1-c","text":"Ganancia 100 µV/div y barrido de 10 ms/div, como en la aguja.","isCorrect":false},{"id":"gain-q1-d","text":"Ganancia 2 mV/div y filtros de 20 Hz a 2 kHz, compartidos con el SNAP.","isCorrect":false}],"explanation":"Esos son los números del motor en la lección. La segunda opción es la del sensitivo: el SNAP, en milivoltios por división, desaparecería de la pantalla.\n\n📚 Referencia: McClellan C, McLaughlin M. Quality in Electrodiagnostic Studies: A Guide for Referring Physicians. Missouri Medicine (2019).","citations":[{"authors":"McClellan C, McLaughlin M","title":"Quality in Electrodiagnostic Studies: A Guide for Referring Physicians","journal":"Missouri Medicine","year":2019}]},{"id":"gain-q2","sortOrder":1,"type":"single","difficulty":"intermediate","stem":"Un SNAP de 25 µV se muestra con ganancia de 5 mV/div y barrido de 5 ms/div. ¿Por qué la lección considera mala esa configuración?","options":[{"id":"gain-q2-a","text":"El sensitivo pide 10–20 µV/div y 1–2 ms/div. A 5 mV/div el SNAP queda plano e ilegible.","isCorrect":true},{"id":"gain-q2-b","text":"Es la configuración sensitiva correcta; 5 mV/div equivale a 20 µV/div.","isCorrect":false},{"id":"gain-q2-c","text":"El barrido de 5 ms/div alarga la latencia pico en 3 ms.","isCorrect":false},{"id":"gain-q2-d","text":"Esa ganancia solo falla si la temperatura es menor de 30 °C.","isCorrect":false}],"explanation":"5 mV es 5 000 µV. Un SNAP de 25 µV no ocupa ni una fracción de división. La lección pone el sensitivo en 10–20 µV/div y 1–2 ms/div, con filtros de 20 Hz a 2 kHz.\n\n📚 Referencia: Buschbacher RM, Kumbhare D, Robinson L. Buschbacher's Manual of Nerve Conduction Studies (3rd ed). Demos Medical (2015).","citations":[{"authors":"Buschbacher RM, Kumbhare D, Robinson L","title":"Buschbacher's Manual of Nerve Conduction Studies (3rd ed)","journal":"Demos Medical","year":2015}]},{"id":"gain-q3","sortOrder":2,"type":"single","difficulty":"advanced","stem":"Se va a promediar un mediano sensitivo. ¿Qué filtro de paso bajo (high-pass) corresponde al sensitivo de la lección, y no al motor?","options":[{"id":"gain-q3-a","text":"20 Hz, con el filtro alto en 2 kHz.","isCorrect":true},{"id":"gain-q3-b","text":"2 Hz, con el filtro alto en 10 kHz.","isCorrect":false},{"id":"gain-q3-c","text":"500 Hz, para borrar el componente lento del SNAP.","isCorrect":false},{"id":"gain-q3-d","text":"Sin filtros, porque el promedio ya limpia la señal.","isCorrect":false}],"explanation":"La lección separa filtros: motor 2 Hz–10 kHz y sensitivo 20 Hz–2 kHz. Un high-pass de 500 Hz se come el SNAP.\n\n📚 Referencia: Chen S, Andary M, Buschbacher R, et al.. Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations. Muscle & Nerve (2016). https://doi.org/10.1002/mus.25203","citations":[{"authors":"Chen S, Andary M, Buschbacher R, et al.","title":"Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations","journal":"Muscle & Nerve","year":2016,"url":"https://doi.org/10.1002/mus.25203"}]},{"id":"gain-q4","sortOrder":3,"type":"single","difficulty":"intermediate","stem":"Un CMAP de 8 mV se registró a 20 µV/div. El trazo se sale de la pantalla y la amplitud queda saturada. ¿Qué hay que cambiar?","options":[{"id":"gain-q4-a","text":"Pasar a ganancia motora, 2–5 mV/div, y a un barrido de 2–5 ms/div.","isCorrect":true},{"id":"gain-q4-b","text":"Dejar 20 µV/div y promediar 20 trazos para “bajar” el CMAP.","isCorrect":false},{"id":"gain-q4-c","text":"Subir el high-pass a 2 kHz.","isCorrect":false},{"id":"gain-q4-d","text":"Medir la amplitud en el borde de la pantalla y anotarla como 8 mV.","isCorrect":false}],"explanation":"Un CMAP de milivoltios no se mide en una escala de microvoltios: satura. El promedio no reduce un potencial saturado.\n\n📚 Referencia: Dillingham T, Chen S, Andary M, et al.. Establishing high quality reference values for nerve conduction studies (AANEM Normative Data Task Force). Muscle & Nerve (2016). https://doi.org/10.1002/mus.25204","citations":[{"authors":"Dillingham T, Chen S, Andary M, et al.","title":"Establishing high quality reference values for nerve conduction studies (AANEM Normative Data Task Force)","journal":"Muscle & Nerve","year":2016,"url":"https://doi.org/10.1002/mus.25204"}]}],"examQuestions":[{"module_id":"safety-qc","topic_id":"sweep-gain","topic_name":"Configuración Sensitiva vs Motora","island_name":"EMG","stem":"El técnico deja el equipo como estaba tras un mediano motor (5 mV/div, 5 ms/div, filtros 2 Hz–10 kHz) y pasa al mediano sensitivo de dedo 2 sin tocar la perilla.","difficulty":2,"is_critical":false,"findings":[{"type":"SIGN","label":"Ganancia heredada","value":"5 mV/div"},{"type":"SIGN","label":"Barrido y filtros heredados","value":"5 ms/div, 2 Hz–10 kHz"}],"options":[{"text":"Cambiar a 10–20 µV/div, barrido 1–2 ms/div y filtros 20 Hz–2 kHz antes de aceptar el SNAP.","is_correct":true,"feedback":"Es la configuración sensitiva de la lección. Con la escala motora el SNAP no se ve."},{"text":"Promediar 30 trazos en 5 mV/div: el promedio cambia la escala.","is_correct":false,"feedback":"Promediar mejora la relación señal-ruido; no convierte milivoltios en microvoltios."},{"text":"Informar SNAP ausente.","is_correct":false,"feedback":"Ausente en una escala motora no es un SNAP ausente."},{"text":"Dejar los filtros motores, que son más abiertos y por eso mejores para el sensitivo.","is_correct":false,"feedback":"La lección fija 20 Hz–2 kHz para el sensitivo, no 2 Hz–10 kHz."}],"pearl":"Motor: mV y 2–5 ms/div. Sensitivo: µV y 1–2 ms/div. No se hereda la perilla de uno al otro.","source_reference":"McClellan C, McLaughlin M. Quality in Electrodiagnostic Studies: A Guide for Referring Physicians. Missouri Medicine (2019).","tags":["safety-qc","sweep-gain"],"status":"DRAFT"}]}$payload$::jsonb,
